const keys = {};
  let thrustPlaying = false;
  addEventListener('keydown', e => {
    keys[e.code] = true;
    if (e.code === 'ArrowUp' && !thrustPlaying) {
      thrustAudio.currentTime = 0;
      thrustAudio.play();
      thrustPlaying = true;
    }
  });
  addEventListener('keyup', e => {
    keys[e.code] = false;
    if (e.code === 'ArrowUp') {
      thrustAudio.pause();
      thrustAudio.currentTime = 0;
      thrustPlaying = false;
    }
  });

